// Selling: open a 2 of 3 vault with an operator and an arbiter, then publish
// the auction terms. The vault key is generated by the three seats together;
// this browser keeps only the seller's share.

const BONDS = [1e5, 2e5, 5e5, 1e6, 2e6, 5e6, 1e7, 2e7, 5e7, 1e8, 2e8, 5e8, 1e9, 2e9, 5e9];

export async function renderSell(_, ctx) {
  const { S, call, api, busy, toast, esc, zec, parseZec, unit, loadSeats, saveSeats } = ctx;
  // Never plan on blocks coming faster than the network's target spacing
  // (75 s on mainnet, 25 s on testnet since NU7), however quick the last
  // few were: unsealing before the bidding height is reached would end
  // bidding early.
  const target = { main: 75, test: 25 }[S.net] || 20;
  const secsPerBlock = () => Math.max(ctx.blockSecs(), target);
  const view = document.getElementById("view");
  await S.ready;
  await ctx.refreshChain();
  if (!S.info) {
    view.innerHTML = `<div class="panel"><h2>Can't reach the coordinator</h2></div>`;
    return;
  }
  if (!S.wallet || !S.pass) {
    view.innerHTML = `
      <div class="panel" style="max-width:560px;margin:30px auto">
        <span class="eyebrow">Sell</span>
        <h2>Open your wallet to sell</h2>
        <p class="muted">You'll be paid into your Tacit wallet, and it holds your seat in the auction's vault.</p>
        <a class="btn primary" href="#/wallet">Open wallet</a>
      </div>`;
    return;
  }

  const agents = await api("/v1/agents").catch(() => []);
  const runBy = (a) => (a && a.run_by) || "unnamed";
  const operators = agents.filter((a) => a.role === "operator");
  // Arbiters run by someone other than the first operator come first, so the
  // default pairing never puts two of the three key shares with one party.
  const arbiters = agents
    .filter((a) => a.role === "arbiter")
    .sort((x, y) => (runBy(x) === runBy(operators[0])) - (runBy(y) === runBy(operators[0])));
  const agentOption = (a) => `<option value="${a.seat}">${esc(a.name)} · run by ${esc(runBy(a))}</option>`;
  const seats = await loadSeats();
  const listings = seats.vaults.filter((v) => v.kind === "auction");

  view.innerHTML = `
    <span class="eyebrow">Sell</span>
    <h1 style="font-size:clamp(28px,4vw,42px)">List something in a sealed auction</h1>
    <p class="muted" style="max-width:700px">You, an operator and an arbiter generate a fresh 2-of-3 vault together. Bidders' bonds go into it, and when the bids unseal the operator and arbiter settle automatically. They can only pay out exactly what the rules say, because each one recomputes the result and refuses anything else.</p>
    <div class="split" style="margin-top:22px">
      <div class="panel">
        <h2>Auction</h2>
        <div class="stack">
          <label class="field"><span>What are you selling?</span><input id="item" maxlength="256" placeholder="e.g. Signed first edition, lot 7" /></label>
          <div class="grid cols-2" style="grid-template-columns:1fr 1fr">
            <label class="field"><span>Reserve price</span><div class="input-suffix"><input id="reserve" inputmode="decimal" value="0.1" /><b>${unit()}</b></div></label>
            <label class="field"><span>Bond (also the highest bid)</span><select id="bond">${BONDS.map((b) => `<option value="${b}" ${b === 1e8 ? "selected" : ""}>${zec(b)} ${unit()}</option>`).join("")}</select></label>
          </div>
          <div class="grid cols-2" style="grid-template-columns:1fr 1fr">
            <label class="field"><span>Bidding window</span><select id="blocks">
              ${[
                [10, "10 minutes"],
                [30, "30 minutes"],
                [60, "1 hour"],
                [1440, "1 day"],
              ]
                .map(([m, label]) => {
                  const b = Math.max(2, Math.ceil((m * 60) / target));
                  return `<option value="${b}" ${m === 30 ? "selected" : ""}>${label} (${b} blocks)</option>`;
                })
                .join("")}</select></label>
            <label class="field"><span>Price rule</span><select id="rule"><option value="second_price">Second price (Vickrey)</option><option value="first_price">First price</option></select></label>
          </div>
          <div class="grid cols-2" style="grid-template-columns:1fr 1fr">
            <label class="field"><span>Operator</span><select id="op">${operators.map(agentOption).join("") || `<option value="">none online</option>`}</select></label>
            <label class="field"><span>Arbiter</span><select id="arb">${arbiters.map(agentOption).join("") || `<option value="">none online</option>`}</select></label>
          </div>
          <div id="custody" class="notice" style="font-size:14px"></div>
          <button class="btn primary" id="go">Create vault and publish</button>
        </div>
      </div>
      <div>
        <div class="panel">
          <h2>What happens</h2>
          <div class="stack muted" style="font-size:14px">
            <p style="margin:0"><b style="color:var(--text)">1. Key generation.</b> Your browser, the operator and the arbiter run FROST key generation through sealed envelopes. Nobody, the coordinator included, ever sees the whole key.</p>
            <p style="margin:0"><b style="color:var(--text)">2. Publish.</b> The terms, including the vault's public audit key, are hashed into the auction id. Changing any term makes a different auction.</p>
            <p style="margin:0"><b style="color:var(--text)">3. Bids unseal.</b> Bids open at the drand round right after bidding closes, then the vault pays you the clearing price and refunds everyone else.</p>
          </div>
        </div>
        <div class="panel">
          <h2>Your listings</h2>
          ${listings.length ? `<table><tbody>${listings.map((l) => `<tr><td><a href="#/auction/${l.ref}">${esc(l.item)}</a></td><td class="num faint mono">${l.ref.slice(0, 8)}</td></tr>`).join("")}</tbody></table>` : `<p class="muted">Nothing listed yet.</p>`}
        </div>
      </div>
    </div>`;

  // Says plainly who could move the money together.
  const custody = () => {
    const el = view.querySelector("#custody");
    const op = agents.find((a) => a.seat === view.querySelector("#op").value);
    const arb = agents.find((a) => a.seat === view.querySelector("#arb").value);
    if (!op || !arb) {
      el.className = "notice";
      el.textContent = "";
      return;
    }
    if (runBy(op) === runBy(arb) && runBy(op) !== "unnamed") {
      el.className = "notice warn";
      el.innerHTML = `Both agents are run by <b>${esc(runBy(op))}</b>, who would then hold two of the vault's three key shares. Pick an arbiter run by someone else, or <a href="#/agents">run one yourself</a>.`;
    } else {
      el.className = "notice good";
      el.innerHTML = `Independent seats: you, <b>${esc(runBy(op))}</b> and <b>${esc(runBy(arb))}</b> each hold one key share. No single party can move the money, and each cosigner pays out only what the rules compute.`;
    }
  };
  view.querySelector("#op").onchange = custody;
  view.querySelector("#arb").onchange = custody;
  custody();

  view.querySelector("#go").onclick = async () => {
    const item = view.querySelector("#item").value.trim();
    const reserve = parseZec(view.querySelector("#reserve").value);
    const bond = Number(view.querySelector("#bond").value);
    const blocks = Number(view.querySelector("#blocks").value);
    const rule = view.querySelector("#rule").value;
    const op = view.querySelector("#op").value;
    const arb = view.querySelector("#arb").value;
    if (!item) return toast("Describe what you're selling", "error");
    if (reserve == null || reserve > bond) return toast("The reserve must be at most the bond", "error");
    if (!op || !arb) return toast("An operator and an arbiter need to be online", "error");
    if (op === arb) return toast("Pick two different agents", "error");

    const b = busy("Opening your auction");
    try {
      const me = await call("seatPublic", { secret: seats.secret });
      const seatList = [me, op, arb];
      // Deposits need the finished vault's address, so every deposit lands
      // above the tip we take now.
      const created = (await api("/v1/chain/info")).tip;
      const room = await api("/v1/rooms", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ seats: seatList, purpose: "dkg" }),
      });
      const share = await call("dkg", { network: S.net, secret: seats.secret, room: room.id, seats: seatList }, b.onProgress);
      b.onProgress({ label: "Publishing the terms", spin: true });
      const tip = (await api("/v1/chain/info")).tip;
      const bidsUntil = tip + blocks;
      // Unseal after the bidding window ends, with a quarter of the window
      // (at least five blocks) of slack, since block times wander.
      const slack = Math.max(5, Math.ceil(blocks / 4));
      const unsealAt = Math.floor(Date.now() / 1000) + Math.ceil((blocks + slack) * secsPerBlock());
      const closeRound = await call("roundAt", { unix: unsealAt });
      const seller = await call("address", { index: ctx.nextRefundIndex() });
      const terms = {
        network: S.net,
        vault_ufvk: share.ufvk,
        seller,
        item,
        created_height: created,
        reserve,
        bond,
        bids_until_height: bidsUntil,
        close_round: closeRound,
        rule,
      };
      const id = await call("auctionId", { terms });
      const rec = await api("/v1/auctions", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(terms),
      });
      if (rec.id !== id) throw new Error("The coordinator computed a different auction id");
      seats.vaults.push({ kind: "auction", ref: id, item, share, created_height: created });
      await saveSeats(seats);
      b.close();
      toast("Auction published", "good");
      location.hash = `#/auction/${id}`;
    } catch (e) {
      b.close();
      toast(e.message, "error");
    }
  };
}
